functions._atsState:
function _atsState() {
  if (!window._atsState_) {
    window._atsState_ = {
      templates: [],
      currentId: null,
      pickerOpen: false,
      promptValues: {},      // {key: chosen value}  (key = DEF key)
      detectedTags: [],      // [key, key, ...]      (dedup'd from defs)
      detectedDefs: [],      // [{key, default, isText, options, warning}, ...]
      logicBlocks: [],       // {{IF:}} / {{ELSEIF:}} / {{ELSE}} / {{ENDIF}} tree
      lastDocText: "",       // most recent doc body text
      sourceOoxml: "",       // snapshot of the "template" doc body for live preview
      sourceText:  "",       // text counterpart for previewing without OOXML
      livePreview: true,     // auto-apply on every value change
      previewTimer: null,    // debounce handle for live preview
      filterText: "",
      saveTimer: null,
    };
  }
  return window._atsState_;
}

// ── IDB helpers ─────────────────────────────────────────────────────

functions._atsLoadAll:
function _atsLoadAll() {
  if (!window.eli || !window.eli.storage) return Promise.resolve([]);
  return window.eli.storage.getAll("bd_templates").then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && r.id && String(r.id).charAt(0) !== "_";
    });
  }).catch(function () { return []; });
}

functions._atsSaveRow:
function _atsSaveRow(tpl) {
  if (!tpl || !tpl.id) return Promise.reject(new Error("missing id"));
  tpl.lastUpdated = Date.now();
  return window.eli.storage.put("bd_templates", tpl);
}

functions._atsCurrent:
function _atsCurrent() {
  var st = _atsState();
  return st.templates.find(function (t) { return t.id === st.currentId; }) || null;
}

// ── Word interop ────────────────────────────────────────────────────
// Read the current doc body's text + OOXML. Used to detect tags and
// save the current Word state as a template.

functions._atsReadDoc:
function _atsReadDoc() {
  if (!window.eli || !window.eli.host || !window.eli.host.runRaw) {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  return window.eli.host.runRaw("ats:read_doc", function (context) {
    var body = context.document.body;
    body.load("text");
    var ooxml = body.getOoxml();
    return context.sync().then(function () {
      return { text: body.text || "", ooxml: ooxml.value || "" };
    });
  });
}

// Insert text at the current selection (cursor) in Word.

functions._atsInsertAtCursor:
function _atsInsertAtCursor(text) {
  return window.eli.host.runRaw("ats:insert_at_cursor", function (context) {
    var sel = context.document.getSelection();
    sel.insertText(text, Word.InsertLocation.replace);
    return context.sync();
  });
}

// Wrap the current selection in prefix/suffix (used for conditional blocks).

functions._atsWrapSelection:
function _atsWrapSelection(prefix, suffix) {
  return window.eli.host.runRaw("ats:wrap_sel", function (context) {
    var sel = context.document.getSelection();
    sel.load("text");
    return context.sync().then(function () {
      var inner = sel.text || "";
      sel.insertText(prefix + inner + suffix, Word.InsertLocation.replace);
      return context.sync();
    });
  });
}

// Live-preview pipeline. Restores the snapshotted source OOXML, then
// runs BD's actual template-resolution steps in sequence:
//   1) Evaluate {{IF/ELSEIF/ELSE/ENDIF}} blocks, delete losing branches
//   2) Replace every {{key}} fill marker with the chosen value
//   3) Strip leftover scaffolds ({{DEF:...}}, {{TITLE:...}}, {{DELETE_LINE}}, {{ENTER}}, any other {{...}})
// The source snapshot stays in state so the next change starts fresh.
// FROM tools/build_draft/init.js _step1a / _step1b / _step1c / _step1d / _step1f.

functions._atsApplyTemplate:
function _atsApplyTemplate(values) {
  var st = _atsState();
  if (!st.sourceOoxml) {
    return Promise.reject(new Error("No source captured — load a template or click 🔄 first."));
  }
  values = values || {};
  return _atsRestoreSource()
    .then(function () { return _atsEvalIfBlocks(values); })
    .then(function () { return _atsReplaceFillMarkers(values); })
    .then(function () { return _atsStripScaffolds(); });
}

// Reinsert the captured source OOXML so subsequent eval passes operate
// on the full template (not the previously-rendered preview).

functions._atsRestoreSource:
function _atsRestoreSource() {
  var st = _atsState();
  return window.eli.host.runRaw("ats:restore_source", function (context) {
    context.document.body.insertOoxml(st.sourceOoxml, Word.InsertLocation.replace);
    return context.sync();
  });
}

// Step 1: walk every {{IF:.../ELSEIF:.../ELSE/ENDIF}} marker, build
// nesting plans, and delete the losing segments. Deepest-first so
// nested deletions don't invalidate outer ranges.

functions._atsEvalIfBlocks:
function _atsEvalIfBlocks(values) {
  return window.eli.host.runRaw("ats:eval_if_blocks", function (context) {
    var body = context.document.body;
    var tagSearch = body.search("\\{\\{[!\\}]@\\}\\}", { matchWildcards: true });
    tagSearch.load(["text", "index"]);
    return context.sync().then(function () {
      var tags = [];
      for (var i = 0; i < tagSearch.items.length; i++) {
        var rawTxt = tagSearch.items[i].text.replace(/[{}]/g, "").trim();
        if (rawTxt.indexOf("IF:") === 0 || rawTxt.indexOf("ELSEIF:") === 0
            || rawTxt.indexOf("ELSE") === 0 || rawTxt.indexOf("ENDIF") === 0) {
          tags.push({ range: tagSearch.items[i], text: rawTxt, index: i });
        }
      }
      var blockStack = [];
      var executionPlans = [];
      for (var j = 0; j < tags.length; j++) {
        var t = tags[j];
        var txt = t.text;
        if (txt.indexOf("IF:") === 0) {
          var blk = { segments: [], startTagIndex: j, depth: blockStack.length };
          blk.segments.push({ condition: txt.substring(3).trim(), tagIndex: j });
          blockStack.push(blk);
        } else if (txt.indexOf("ELSEIF:") === 0) {
          var blk2 = blockStack.length ? blockStack[blockStack.length - 1] : null;
          if (blk2) {
            blk2.segments[blk2.segments.length - 1].endTagIndex = j;
            blk2.segments.push({ condition: txt.substring(7).trim(), tagIndex: j });
          }
        } else if (txt.indexOf("ELSE") === 0) {
          var blk3 = blockStack.length ? blockStack[blockStack.length - 1] : null;
          if (blk3) {
            blk3.segments[blk3.segments.length - 1].endTagIndex = j;
            blk3.segments.push({ condition: "true", tagIndex: j });
          }
        } else if (txt.indexOf("ENDIF") === 0) {
          var done = blockStack.pop();
          if (done) {
            done.segments[done.segments.length - 1].endTagIndex = j;
            executionPlans.push({ segments: done.segments, finalEndTagIndex: j, depth: done.depth });
          }
        }
      }
      executionPlans.sort(function (a, b) { return b.depth - a.depth; });
      for (var p = 0; p < executionPlans.length; p++) {
        var plan = executionPlans[p];
        var winning = -1;
        for (var s = 0; s < plan.segments.length; s++) {
          if (_atsEvalCondition(plan.segments[s].condition, values)) { winning = s; break; }
        }
        if (winning > -1) {
          for (var s2 = 0; s2 < plan.segments.length; s2++) {
            var seg = plan.segments[s2];
            var startTag = tags[seg.tagIndex].range;
            if (seg.endTagIndex === undefined) continue;
            var endTag = tags[seg.endTagIndex].range;
            if (s2 === winning) {
              startTag.delete();
            } else {
              var rng = startTag.getRange("Start").expandTo(endTag.getRange("Start"));
              rng.delete();
            }
          }
          if (tags[plan.finalEndTagIndex]) tags[plan.finalEndTagIndex].range.delete();
        } else if (plan.segments.length && plan.finalEndTagIndex !== undefined) {
          var firstTag = tags[plan.segments[0].tagIndex].range;
          var finalTag = tags[plan.finalEndTagIndex].range;
          var del = firstTag.getRange("Start").expandTo(finalTag.getRange("End"));
          del.delete();
        }
      }
      return context.sync();
    });
  });
}

// Step 2: each chosen value replaces every {{key}} or {{key:formatter}}.

functions._atsReplaceFillMarkers:
function _atsReplaceFillMarkers(values) {
  var keys = Object.keys(values).filter(function (k) {
    return values[k] != null && String(values[k]).length > 0;
  });
  if (!keys.length) return Promise.resolve();
  return window.eli.host.runRaw("ats:replace_fill_markers", function (context) {
    var body = context.document.body;
    var searches = keys.map(function (key) {
      var pattern = "\\{\\{" + key + "*\\}\\}";
      var res = body.search(pattern, { matchWildcards: true });
      res.load("text");
      return { key: key, res: res };
    });
    return context.sync().then(function () {
      searches.forEach(function (s) {
        if (!s.res.items) return;
        for (var i = 0; i < s.res.items.length; i++) {
          var inner = s.res.items[i].text.replace(/[{}]/g, "");
          // Only replace if the inner is exactly the key, or "key:formatter".
          // Avoids matching {{IF:counterparty==X}} when key="counterparty".
          if (inner === s.key || inner.indexOf(s.key + ":") === 0) {
            s.res.items[i].insertText(String(values[s.key]), Word.InsertLocation.replace);
          }
        }
      });
      return context.sync();
    });
  });
}

// Step 3: strip leftover scaffolding so the preview is clean. Same
// regex set BD uses in step1c / step1d / step1f.

functions._atsStripScaffolds:
function _atsStripScaffolds() {
  return window.eli.host.runRaw("ats:strip_scaffolds", function (context) {
    var body = context.document.body;
    var defs = body.search("\\{\\{DEF:*\\}\\}", { matchWildcards: true });
    var titles = body.search("\\{\\{TITLE:*\\}\\}", { matchWildcards: true });
    var del = body.search("\\{\\{DELETE_LINE\\}\\}", { matchWildcards: true });
    var ent = body.search("\\{\\{ENTER\\}\\}", { matchWildcards: true });
    defs.load("items"); titles.load("items"); del.load("items"); ent.load("items");
    return context.sync().then(function () {
      for (var i = defs.items.length - 1; i >= 0; i--) defs.items[i].delete();
      for (var k = titles.items.length - 1; k >= 0; k--) titles.items[k].delete();
      for (var d = del.items.length - 1; d >= 0; d--) {
        try { del.items[d].paragraphs.getFirst().delete(); } catch (e) {}
      }
      for (var e2 = ent.items.length - 1; e2 >= 0; e2--) {
        ent.items[e2].insertText("​", Word.InsertLocation.replace);
      }
      return context.sync().then(function () {
        // Strip any other surviving {{...}} (malformed, unanswered).
        var leftovers = body.search("\\{\\{*\\}\\}", { matchWildcards: true });
        leftovers.load("text");
        return context.sync().then(function () {
          for (var L = leftovers.items.length - 1; L >= 0; L--) {
            try { leftovers.items[L].delete(); } catch (e) {}
          }
          return context.sync();
        });
      });
    });
  });
}

// Snapshot the doc body's OOXML to IDB under STORE_CONFIG row id
// _template_studio_snapshot_<templateId>. Restore writes it back.

functions._atsSnapshot:
function _atsSnapshot() {
  var tpl = _atsCurrent();
  var id = tpl ? tpl.id : "_no_template";
  return _atsReadDoc().then(function (state) {
    return window.eli.storage.put("config", {
      key: "_template_studio_snapshot_" + id,
      ooxml: state.ooxml,
      capturedAt: Date.now(),
    }).then(function () { return true; });
  });
}

functions._atsRestore:
function _atsRestore() {
  var tpl = _atsCurrent();
  var id = tpl ? tpl.id : "_no_template";
  return window.eli.storage.get("config", "_template_studio_snapshot_" + id).then(function (row) {
    if (!row || !row.ooxml) {
      if (typeof showToast === "function") showToast("No snapshot to restore.", "warn");
      return false;
    }
    return window.eli.host.runRaw("ats:restore", function (context) {
      context.document.body.insertOoxml(row.ooxml, Word.InsertLocation.replace);
      return context.sync();
    }).then(function () {
      if (typeof showToast === "function") showToast("✓ Restored to snapshot", "ok");
      return true;
    });
  });
}

// Load the saved template's content into the Word doc (snapshot first).

functions._atsLoadIntoDoc:
function _atsLoadIntoDoc() {
  var tpl = _atsCurrent();
  if (!tpl) return Promise.resolve(false);
  if (typeof showToast === "function") showToast("⏳ Snapshotting + loading…", "info");
  return _atsSnapshot().then(function () {
    return window.eli.host.runRaw("ats:load_template", function (context) {
      var body = context.document.body;
      var s = String(tpl.content || "").trim();
      if (s.charAt(0) === "{") {
        try {
          var parsed = JSON.parse(s);
          if (parsed.body) {
            body.insertOoxml(parsed.body, Word.InsertLocation.replace);
            return context.sync();
          }
        } catch (e) { /* fall through */ }
      }
      body.insertText(s, Word.InsertLocation.replace);
      return context.sync();
    });
  }).then(function () {
    if (typeof showToast === "function") showToast("✓ Template loaded — edit in Word.", "ok");
    _atsDetectTagsLive();
    return true;
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Load failed: " + (err && err.message || "unknown"), "err");
    return false;
  });
}

// Capture the current Word doc body as the template's content. Saves
// to IDB. Storing as JSON envelope so headers/footers can be added
// later — currently captures body only.

functions._atsSaveFromDoc:
function _atsSaveFromDoc() {
  var tpl = _atsCurrent();
  if (!tpl) return Promise.resolve(false);
  if (tpl.locked) {
    if (typeof showToast === "function") showToast("Template is locked.", "warn");
    return Promise.resolve(false);
  }
  return _atsReadDoc().then(function (state) {
    tpl.content = JSON.stringify({ body: state.ooxml, sections: [] });
    return _atsSaveRow(tpl);
  }).then(function () {
    return _atsLoadAll();
  }).then(function (all) {
    _atsState().templates = all;
    _atsRenderAll();
    _atsSetSaveState("saved");
    if (typeof showToast === "function") showToast("✓ Saved Word doc → " + (tpl.name || tpl.id), "ok");
    setTimeout(function () { _atsSetSaveState(""); }, 2000);
    return true;
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Save failed: " + (err && err.message || "unknown"), "err");
    return false;
  });
}

// Build Draft DEF-syntax extractor. Parses every {{DEF:key=default|opts|warning}}
// in the template. This mirrors BD engine.js _parseLogicDefs so the
// prompts here match the BD wizard 1:1. Returns:
//   [{ key, default, isText, options, warning, raw, index }, ...]
// where:
//   - default = the "=default" portion after the key (post-equals text)
//   - isText  = options started with "*", treat as free text input
//   - options = array of dropdown options (empty when isText)
//   - warning = optional third pipe segment (admin guidance)
// FROM tools/build_draft/engine.js _parseLogicDefs (line 198).

functions._atsExtractDefs:
function _atsExtractDefs(text) {
  var src = String(text || "");
  var defs = [];
  var seen = {};
  var re = /\{\{\s*DEF:([^{}]+?)\}\}/g;
  var m;
  while ((m = re.exec(src)) !== null) {
    var clean = (m[1] || "").trim();
    var pipe = clean.split("|");
    var defPart = pipe[0].trim();
    var optionsPart = pipe.length > 1 ? pipe[1].trim() : "";
    var warning = pipe.length > 2 ? pipe[2].trim() : "";
    if (!optionsPart) continue; // BD requires options part
    var defSplit = defPart.split("=");
    var key = defSplit[0].trim();
    if (!key) continue;
    if (seen[key]) continue; // dedup — keep first occurrence
    seen[key] = true;
    var explicitDefault = defSplit.length > 1 ? defSplit[1].trim() : "";
    var isText = optionsPart.charAt(0) === "*";
    var textDefault = isText ? optionsPart.substring(1).trim() : "";
    defs.push({
      key: key,
      default: explicitDefault || textDefault,
      isText: isText,
      options: isText ? [] : optionsPart.split(",").map(function (o) { return o.trim(); }).filter(Boolean),
      warning: warning,
      raw: m[0],
      index: m.index,
    });
  }
  return defs;
}

// Mirror the DEF list onto tpl.prompts so the saved template carries
// its question set. Schema is derived from the {{DEF:...}} syntax —
// we never override what the doc says. Returns whether tpl.prompts
// changed (caller saves to IDB).

functions._atsSyncPromptsFromDefs:
function _atsSyncPromptsFromDefs(tpl, defs) {
  if (!tpl) return false;
  var fresh = defs.map(function (d) {
    return {
      name: d.key, label: d.key,
      type: d.isText ? "text" : "dropdown",
      options: d.options.slice(),
      default: d.default || "",
      warning: d.warning || "",
    };
  });
  var prev = JSON.stringify(tpl.prompts || []);
  var next = JSON.stringify(fresh);
  if (prev === next) return false;
  tpl.prompts = fresh;
  return true;
}

// Stack-based parse of Build Draft IF blocks. Recognizes:
//   {{IF:cond}}  {{ELSEIF:cond}}  {{ELSE}}  {{ENDIF}}
// Returns an array of root blocks (with nested children + segment list).
// Each block:
//   { segments: [{kind, condition, pos, line, raw}], closePos, closeLine,
//     children, depth, error }
// FROM tools/build_draft/init.js _step1a_executePlans (line 692).

functions._atsTraceLogicBlocks:
function _atsTraceLogicBlocks(text) {
  var src = String(text || "");
  var re = /\{\{\s*(IF:|ELSEIF:|ELSE|ENDIF)\s*([^{}]*)\}\}/g;
  var tokens = [];
  var m;
  while ((m = re.exec(src)) !== null) {
    var raw1 = m[1];
    var arg = (m[2] || "").trim();
    var kind = raw1.replace(":", "");
    if (raw1.charAt(raw1.length - 1) === ":" && !arg) continue; // {{IF:}} with no cond — skip
    var lineNo = src.slice(0, m.index).split(/\r?\n/).length;
    tokens.push({ kind: kind, arg: arg, pos: m.index, len: m[0].length, raw: m[0], line: lineNo });
  }
  var root = [];
  var stack = [];
  tokens.forEach(function (tok) {
    if (tok.kind === "IF") {
      var block = {
        segments: [{ kind: "IF", condition: tok.arg, pos: tok.pos, line: tok.line, raw: tok.raw }],
        closePos: null, closeLine: null,
        children: [],
        depth: stack.length,
        error: null,
      };
      if (stack.length) stack[stack.length - 1].children.push(block);
      else root.push(block);
      stack.push(block);
    } else if (tok.kind === "ELSEIF") {
      if (!stack.length) {
        root.push({ segments: [{ kind: "ELSEIF", condition: tok.arg, pos: tok.pos, line: tok.line, raw: tok.raw }], closePos: null, closeLine: null, children: [], depth: 0, error: "orphan {{ELSEIF}} at line " + tok.line });
        return;
      }
      stack[stack.length - 1].segments.push({ kind: "ELSEIF", condition: tok.arg, pos: tok.pos, line: tok.line, raw: tok.raw });
    } else if (tok.kind === "ELSE") {
      if (!stack.length) {
        root.push({ segments: [{ kind: "ELSE", condition: "", pos: tok.pos, line: tok.line, raw: tok.raw }], closePos: null, closeLine: null, children: [], depth: 0, error: "orphan {{ELSE}} at line " + tok.line });
        return;
      }
      stack[stack.length - 1].segments.push({ kind: "ELSE", condition: "", pos: tok.pos, line: tok.line, raw: tok.raw });
    } else if (tok.kind === "ENDIF") {
      if (!stack.length) {
        root.push({ segments: [{ kind: "ENDIF", condition: "", pos: tok.pos, line: tok.line, raw: tok.raw }], closePos: tok.pos, closeLine: tok.line, children: [], depth: 0, error: "orphan {{ENDIF}} at line " + tok.line });
        return;
      }
      var top = stack.pop();
      top.closePos = tok.pos;
      top.closeLine = tok.line;
    }
  });
  while (stack.length) {
    var unfin = stack.pop();
    unfin.error = (unfin.error || "") + " · unclosed (no matching {{ENDIF}})";
  }
  return root;
}

// Mirror of BD engine.js evalLogicCondition. Used to evaluate IF/ELSEIF
// conditions against the current value map during preview rendering.

functions._atsEvalCondition:
function _atsEvalCondition(condStr, values) {
  if (condStr === "true") return true;
  var op = condStr.indexOf("!=") !== -1 ? "!=" : "==";
  var parts = condStr.split(op);
  if (parts.length < 2) return false;
  var k = parts[0].trim();
  var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
  var actual = values && values[k];
  if (actual === undefined || actual === null || actual === "") return false;
  return op === "==" ? rhs.indexOf(String(actual)) !== -1 : rhs.indexOf(String(actual)) === -1;
}

// Scan current Word doc body. Extracts {{DEF:...}} placeholders, traces
// {{IF:...}}/{{ELSEIF:...}}/{{ELSE}}/{{ENDIF}} blocks, and snapshots
// the source body so live-preview can restore + re-evaluate on every
// value change. Syncs the active template's prompt schema 1:1 with the
// DEF list in the doc — admin edits placeholders in Word, the panel
// follows. (No manual schema editor — the doc IS the schema.)

functions._atsDetectTagsLive:
function _atsDetectTagsLive() {
  return _atsReadDoc().then(function (state) {
    var st = _atsState();
    st.lastDocText = state.text || "";

    var defs = _atsExtractDefs(st.lastDocText);
    st.detectedDefs = defs;
    st.detectedTags = defs.map(function (d) { return d.key; });
    st.logicBlocks = _atsTraceLogicBlocks(st.lastDocText);

    // Capture the source on first detection. Subsequent scans only
    // refresh source if the doc still looks like a template (has DEF
    // or IF markers) — otherwise we'd snapshot the post-substitution
    // doc and lose the ability to restore.
    var looksTemplate = (defs.length > 0) || (st.logicBlocks.length > 0);
    if (looksTemplate && state.ooxml) {
      st.sourceOoxml = state.ooxml;
      st.sourceText = state.text || "";
    }

    var tpl = _atsCurrent();
    if (tpl && !tpl.locked) {
      var changed = _atsSyncPromptsFromDefs(tpl, defs);
      if (changed) {
        _atsSaveRow(tpl).catch(function () {});
      }
    }

    _atsRenderDetected();
    _atsRenderPrompts();
    _atsRenderLogicTree();
    return { tags: st.detectedTags, defs: defs, blocks: st.logicBlocks };
  }).catch(function () { return { tags: [], defs: [], blocks: [] }; });
}

// Locate a substring in the Word doc and select/scroll-into-view.
// Used by click-to-jump on logic blocks + BD prompts.

functions._atsScrollToInDoc:
function _atsScrollToInDoc(needle) {
  if (!needle) return Promise.resolve(false);
  var s = String(needle).trim();
  if (!s) return Promise.resolve(false);
  // Word's body.search has a 250-char limit and dislikes some special
  // characters — trim to a safe snippet.
  var snippet = s.slice(0, 200).replace(/[\r\n\t]+/g, " ");
  return window.eli.host.runRaw("ats:scroll_to", function (context) {
    var r = context.document.body.search(snippet, { matchCase: false, ignorePunct: true, ignoreSpace: true });
    r.load("items");
    return context.sync().then(function () {
      if (!r.items || !r.items.length) return false;
      try { r.items[0].select(); r.items[0].scrollIntoView(); } catch (e) {}
      return context.sync().then(function () { return true; });
    });
  }).catch(function () { return false; });
}

// Jump to a tag in the SOURCE template. After live preview eats the
// {{DEF:...}} and {{IF:...}} markers, the doc no longer contains them,
// so search alone fails. This wrapper restores the source first (if
// one was captured), pauses live preview so the next dropdown change
// doesn't immediately re-render away the marker, then performs the
// search.

functions._atsJumpToInSource:
function _atsJumpToInSource(needle) {
  var st = _atsState();
  var hadLive = st.livePreview;
  st.livePreview = false;
  var toggle = document.getElementById("atsLivePreview");
  if (toggle && toggle.checked !== false) toggle.checked = false;
  var restore = st.sourceOoxml ? _atsRestoreSource() : Promise.resolve();
  return restore.then(function () {
    return _atsScrollToInDoc(needle);
  }).then(function (found) {
    if (!found && typeof showToast === "function") {
      showToast("Couldn't find that in the doc.", "warn");
    } else if (hadLive && typeof showToast === "function") {
      showToast("Preview paused — re-enable to rebuild from values.", "info");
    }
    return found;
  });
}

// "Return to original" — pauses live preview, restores the captured
// source OOXML so the doc shows the un-substituted template again.
// Values stay in state.promptValues so the next time live preview is
// re-enabled, the rendered doc reflects current picks.

functions._atsReturnToOriginal:
function _atsReturnToOriginal() {
  var st = _atsState();
  if (!st.sourceOoxml) {
    if (typeof showToast === "function") showToast("No source captured yet. Click 📸 Capture source first.", "warn");
    return Promise.resolve(false);
  }
  st.livePreview = false;
  var toggle = document.getElementById("atsLivePreview");
  if (toggle) toggle.checked = false;
  return _atsRestoreSource().then(function () {
    if (typeof showToast === "function") showToast("📜 Restored to the original template.", "ok");
    // Re-detect so prompt list + logic tree refresh.
    return _atsDetectTagsLive();
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Restore failed: " + (err && err.message || "unknown"), "err");
    return false;
  });
}

// ── Save state pill ─────────────────────────────────────────────────

functions._atsSetSaveState:
function _atsSetSaveState(state) {
  var el = document.getElementById("atsSaveState");
  if (!el) return;
  el.classList.remove("_ats_saving", "_ats_saved", "_ats_dirty");
  if (state === "saving") { el.textContent = "Saving…"; el.classList.add("_ats_saving"); }
  else if (state === "saved") { el.textContent = "✓ Saved"; el.classList.add("_ats_saved"); }
  else if (state === "dirty") { el.textContent = "Unsaved"; el.classList.add("_ats_dirty"); }
  else { el.textContent = ""; }
}

// ── Renderers ──────────────────────────────────────────────────────

functions._atsRenderCurrent:
function _atsRenderCurrent() {
  var bar = document.getElementById("atsCurrent");
  if (!bar) return;
  var tpl = _atsCurrent();
  if (!tpl) {
    bar.innerHTML =
      '<div class="_ats_current_left">' +
