    document.getElementById("atsOpenPicker").onclick = function () {
      _atsState().pickerOpen = true;
      _atsRenderPicker();
    };
    return;
  }
  var status = tpl.status || "active";
  var size = String(tpl.content || "").length;
  bar.innerHTML =
    '<div class="_ats_current_left">' +
      '<div class="_ats_current_label">Active Template</div>' +
