functions._atsRenderPicker:
function _atsRenderPicker() {
  var box = document.getElementById("atsPicker");
  if (!box) return;
  var st = _atsState();
  if (st.pickerOpen) box.classList.add("_ats_picker_open");
  else box.classList.remove("_ats_picker_open");
  var bodyEl = document.getElementById("atsPickerBody");
  if (!bodyEl) return;
  var f = (st.filterText || "").toLowerCase();
  var rows = st.templates.filter(function (t) {
    if (!f) return true;
    var hay = ((t.name || "") + " " + (t.agreementType || "") + " " + (t.id || "")).toLowerCase();
    return hay.indexOf(f) !== -1;
  });
  var listHtml = rows.length
    ? rows.map(function (t) {
        var active = (t.id === st.currentId) ? " _ats_active" : "";
        var status = t.status || "active";
        return '<div class="_ats_picker_card' + active + '" data-ats-id="' + _atsEsc(t.id) + '">' +
          '<div class="_ats_picker_card_name">' + _atsEsc(t.name || t.id) + '</div>' +
          '<div class="_ats_picker_card_meta">' +
            '<span class="_ats_pill _ats_pill_' + status + '">' + status + '</span> ' +
            _atsEsc(t.agreementType || "—") +
            ' · ' + Math.round(String(t.content || "").length / 1024) + ' KB' +
          '</div>' +
        '</div>';
      }).join("")
    : '<div style="padding:20px; text-align:center; font-size:10px; color:#94a3b8;">No templates' + (f ? ' match.' : '. Click + New below to create one.') + '</div>';
  bodyEl.innerHTML =
    '<div class="_ats_picker_search">' +
      '<input id="atsPickerSearch" type="text" placeholder="Filter templates…" value="' + _atsEsc(st.filterText) + '">' +
    '</div>' +
    '<div class="_ats_picker_list">' + listHtml + '</div>' +
    '<div class="_ats_picker_footer">' +
      '<button class="_ats_btn _ats_btn_gold" id="atsNew">+ New</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsDuplicate">📋 Duplicate</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsImport">⬆ Import</button>' +
    '</div>';
  document.getElementById("atsPickerSearch").oninput = function () {
    _atsState().filterText = this.value;
    _atsRenderPicker();
  };
  bodyEl.querySelectorAll("[data-ats-id]").forEach(function (c) {
    c.onclick = function () {
      _atsState().currentId = c.getAttribute("data-ats-id");
      _atsState().pickerOpen = false;
      _atsRenderAll();
    };
  });
  document.getElementById("atsNew").onclick = _atsActionNew;
  document.getElementById("atsDuplicate").onclick = _atsActionDuplicate;
  document.getElementById("atsImport").onclick = _atsActionImport;
}

functions._atsRenderDetected:
function _atsRenderDetected() {
  var box = document.getElementById("atsDetectedBody");
  if (!box) return;
  var tags = _atsState().detectedTags || [];
  if (!tags.length) {
    box.innerHTML = '<span class="_ats_detected_empty">No tags found yet. Insert one with the picker below, then click 🔄.</span>';
  } else {
    box.innerHTML = tags.map(function (t) {
      return '<span class="_ats_quick_tag" data-ats-quicktag="' + _atsEsc(t) + '">' + _atsEsc(t) + '</span>';
    }).join("");
    box.querySelectorAll("[data-ats-quicktag]").forEach(function (chip) {
      chip.onclick = function () {
        // Click a detected tag → focus its mock-value input.
        var v = chip.getAttribute("data-ats-quicktag");
        var inp = document.querySelector('[data-ats-mock="' + v + '"]');
        if (inp) inp.focus();
      };
    });
  }
  var countEl = document.getElementById("atsDetectedCount");
  if (countEl) countEl.textContent = tags.length;
}

// Render one row per {{DEF:...}} in the doc. Schema (options/default/
// warning) comes directly from the DEF syntax — no manual editor.
// On value change: write to state.promptValues, then (if livePreview)
// schedule a debounced template re-render. Clicking the chip jumps to
// the first occurrence in Word.

functions._atsRenderPrompts:
function _atsRenderPrompts() {
  var box = document.getElementById("atsPromptList");
  if (!box) return;
  var st = _atsState();
  var defs = st.detectedDefs || [];
  if (!defs.length) {
    box.innerHTML = '<div class="_ats_promptlist_empty">No <code>{{DEF:...}}</code> placeholders found. Insert one in the Word doc, then click 🔄.</div>';
    return;
  }
  box.innerHTML = defs.map(function (d) {
    var v = (st.promptValues[d.key] != null && st.promptValues[d.key] !== "") ? st.promptValues[d.key] : (d.default || "");
    var inputHtml;
    if (d.isText) {
      inputHtml = '<input class="_ats_input" type="text" data-ats-prompt="' + _atsEsc(d.key) + '" value="' + _atsEsc(v) + '" placeholder="' + _atsEsc(d.default || d.key) + '">';
    } else {
      var opts = d.options.map(function (o) {
        var sel = (String(v) === String(o)) ? " selected" : "";
        return '<option value="' + _atsEsc(o) + '"' + sel + '>' + _atsEsc(o) + '</option>';
      }).join("");
      inputHtml =
        '<select class="_ats_select" data-ats-prompt="' + _atsEsc(d.key) + '">' +
          '<option value="">— pick —</option>' + opts +
        '</select>';
    }
    var kindBadge = d.isText
      ? '<span class="_ats_promptrow_type">text</span>'
      : '<span class="_ats_promptrow_type">' + d.options.length + ' opts</span>';
    return '<div class="_ats_promptrow">' +
      '<div class="_ats_promptrow_head">' +
        '<button class="_ats_promptrow_chip" data-ats-promptjump="' + _atsEsc(d.key) + '" title="Jump to {{' + _atsEsc(d.key) + '}} in Word">{{' + _atsEsc(d.key) + '}}</button>' +
        '<span class="_ats_promptrow_label">' + _atsEsc(d.default || d.key) + '</span>' +
        kindBadge +
      '</div>' +
      inputHtml +
      (d.warning ? '<div class="_ats_promptrow_warning">⚠ ' + _atsEsc(d.warning) + '</div>' : '') +
      '</div>';
  }).join("");
  box.querySelectorAll("[data-ats-prompt]").forEach(function (inp) {
    var key = inp.getAttribute("data-ats-prompt");
    var handler = function () {
      _atsState().promptValues[key] = inp.value;
      _atsTriggerPreview();
    };
    inp.oninput = handler;
    inp.onchange = handler;
  });
  box.querySelectorAll("[data-ats-promptjump]").forEach(function (b) {
    b.onclick = function () {
      var n = b.getAttribute("data-ats-promptjump");
      // Restore source first so the {{DEF:...}} declaration is back in
      // the doc, then jump. Fill marker as fallback.
      _atsJumpToInSource("{{DEF:" + n).then(function (found) {
        if (!found) _atsScrollToInDoc("{{" + n + "}}");
      });
    };
  });
}

// Debounced live-preview trigger. Fired by any input change. When
// livePreview is off, this is a no-op — user clicks ⚡ Apply manually.

functions._atsTriggerPreview:
function _atsTriggerPreview() {
  var st = _atsState();
  if (!st.livePreview) return;
  if (st.previewTimer) { clearTimeout(st.previewTimer); st.previewTimer = null; }
  st.previewTimer = setTimeout(function () {
    st.previewTimer = null;
    _atsRunPreview();
  }, 400);
}

// One run of the apply pipeline. Folds in defaults for any DEF the
// user hasn't touched so the doc shows what BD would produce out-of-
// the-box. Re-scans after so prompt/IF tree refresh.

functions._atsRunPreview:
function _atsRunPreview() {
  var st = _atsState();
  var values = Object.assign({}, st.promptValues);
  (st.detectedDefs || []).forEach(function (d) {
    if ((values[d.key] == null || values[d.key] === "") && d.default) {
      values[d.key] = d.default;
    }
  });
  return _atsApplyTemplate(values).catch(function (err) {
    if (typeof showToast === "function") showToast(err && err.message ? err.message : "Preview failed", "err");
  });
}

// Logic block tree — renders the {{IF:...}}/{{ELSEIF:...}}/{{ELSE}}/
// {{ENDIF}} structure. Each block lists every segment (with the segment
// that's CURRENTLY winning highlighted, based on st.promptValues), the
// nested children, and any error markers. Click any segment to jump to
// the corresponding tag in Word.

functions._atsRenderLogicTree:
function _atsRenderLogicTree() {
  var box = document.getElementById("atsLogicTree");
  if (!box) return;
  var st = _atsState();
  var blocks = st.logicBlocks || [];
  if (!blocks.length) {
    box.innerHTML = '<div class="_ats_logic_empty">No conditional blocks found. Wrap a selection with the form above.</div>';
    return;
  }
  var liveValues = Object.assign({}, st.promptValues);
  (st.detectedDefs || []).forEach(function (d) {
    if ((liveValues[d.key] == null || liveValues[d.key] === "") && d.default) liveValues[d.key] = d.default;
  });
  function pickWinning(segments) {
    for (var s = 0; s < segments.length; s++) {
      var seg = segments[s];
      if (seg.kind === "ELSE") return s;
      var cond = (seg.kind === "IF" || seg.kind === "ELSEIF") ? seg.condition : null;
      if (cond !== null && _atsEvalCondition(cond, liveValues)) return s;
    }
    return -1;
  }
  function renderBlock(b, depth) {
    var closed = b.closePos !== null;
    var errCls = b.error ? " _ats_logic_err" : (closed ? "" : " _ats_logic_warn");
    var pad = (depth * 14) + "px";
    var winning = pickWinning(b.segments);
    var segHtml = b.segments.map(function (seg, i) {
      var winCls = (i === winning) ? " _ats_logic_seg_active" : "";
      var label = seg.kind + (seg.condition ? ": " + seg.condition : "");
      return '<button class="_ats_logic_block_cond' + winCls + '" data-ats-trace-jump="' + _atsEsc(seg.raw) + '" title="Jump to ' + _atsEsc(seg.kind) + ' in Word">' +
        _atsEsc(label) +
      '</button>';
    }).join("");
    var endLine = b.closeLine != null ? b.closeLine : "—";
    var openLine = b.segments && b.segments[0] ? b.segments[0].line : "?";
    return '<div class="_ats_logic_block' + errCls + '" style="margin-left:' + pad + ';">' +
      '<div class="_ats_logic_block_head">' +
        '<span class="_ats_logic_block_kind">🔀 if</span>' +
        '<div class="_ats_logic_block_segs">' + segHtml + '</div>' +
        '<span class="_ats_logic_block_lines">L' + openLine + '→' + endLine + '</span>' +
      '</div>' +
      (b.error ? '<div class="_ats_logic_block_err">⚠ ' + _atsEsc(b.error) + '</div>' : '') +
      (b.children && b.children.length
        ? '<div class="_ats_logic_children">' + b.children.map(function (c) { return renderBlock(c, depth + 1); }).join("") + '</div>'
        : '') +
    '</div>';
  }
  box.innerHTML = blocks.map(function (b) { return renderBlock(b, 0); }).join("");
  box.querySelectorAll("[data-ats-trace-jump]").forEach(function (btn) {
    btn.onclick = function () {
      _atsJumpToInSource(btn.getAttribute("data-ats-trace-jump"));
    };
  });

  var errCount = 0, total = 0;
  function walk(arr) {
    arr.forEach(function (b) {
      total++;
      if (b.error || b.closePos === null) errCount++;
      if (b.children) walk(b.children);
    });
  }
  walk(blocks);
  var countEl = document.getElementById("atsLogicCount");
  if (countEl) countEl.textContent = total + (errCount ? " · " + errCount + " ⚠" : "");
}

functions._atsRenderMetadata:
function _atsRenderMetadata() {
  var box = document.getElementById("atsMetadataBody");
  if (!box) return;
  var tpl = _atsCurrent();
  if (!tpl) { box.innerHTML = ""; return; }
  var statusOpts = ["active", "draft", "archived"].map(function (s) {
    return '<option value="' + s + '"' + (((tpl.status || "active") === s) ? " selected" : "") + '>' + s + '</option>';
  }).join("");
  box.innerHTML =
    '<div class="_ats_metaedit">' +
      '<div>' +
        '<div class="_ats_field_label">Name</div>' +
        '<input id="atsFieldName" class="_ats_input" type="text" value="' + _atsEsc(tpl.name || "") + '">' +
      '</div>' +
      '<div>' +
        '<div class="_ats_field_label">Status</div>' +
        '<select id="atsFieldStatus" class="_ats_select">' + statusOpts + '</select>' +
      '</div>' +
    '</div>' +
    '<div style="margin-top:6px;">' +
      '<div class="_ats_field_label">Agreement type</div>' +
      '<input id="atsFieldType" class="_ats_input" type="text" value="' + _atsEsc(tpl.agreementType || "") + '" placeholder="e.g. Non-Disclosure Agreement">' +
    '</div>' +
    '<div style="margin-top:10px; display:flex; gap:4px;">' +
      '<button class="_ats_btn _ats_btn_success" id="atsMetaSave" style="flex:1;">💾 Save metadata</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsLock">' + (tpl.locked ? "🔓 Unlock" : "🔒 Lock") + '</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsExport">⬇</button>' +
      '<button class="_ats_btn _ats_btn_danger" id="atsDelete">🗑</button>' +
    '</div>';
  document.getElementById("atsMetaSave").onclick = function () {
    var t = _atsCurrent();
    if (!t) return;
    t.name = document.getElementById("atsFieldName").value || t.name;
    t.agreementType = document.getElementById("atsFieldType").value || t.agreementType;
    t.status = document.getElementById("atsFieldStatus").value || t.status;
    _atsSetSaveState("saving");
    _atsSaveRow(t).then(function () { return _atsLoadAll(); }).then(function (all) {
      _atsState().templates = all;
      _atsRenderAll();
      _atsSetSaveState("saved");
      setTimeout(function () { _atsSetSaveState(""); }, 1500);
    });
  };
  document.getElementById("atsLock").onclick = _atsActionLock;
  document.getElementById("atsExport").onclick = _atsActionExport;
  document.getElementById("atsDelete").onclick = _atsActionDelete;
}

functions._atsRenderAll:
function _atsRenderAll() {
  var hasTpl = !!_atsCurrent();
  var body = document.getElementById("atsBody");
  if (!body) return;
  if (!hasTpl) {
    body.innerHTML =
      '<div class="_ats_empty_state">' +
        '<div class="_ats_empty_icon">📋</div>' +
        '<div class="_ats_empty_title">No template selected</div>' +
        '<div class="_ats_empty_sub">Open the picker above to load one, or create a new template to start.</div>' +
      '</div>';
    _atsRenderCurrent();
    return;
  }
  body.innerHTML =
    // Word ↔ Template
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📝 Word ↔ Template</div>' +
      '</div>' +
      '<div class="_ats_section_hint">' +
        'Edit the template <b>in Word</b>. Load pulls the saved content into the doc (snapshots first). Save captures the current doc body into this template.' +
      '</div>' +
      '<div class="_ats_grid_2">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsLoadInto">📥 Load into Word</button>' +
        '<button class="_ats_btn _ats_btn_success" id="atsSaveFrom">💾 Save Word doc</button>' +
      '</div>' +
    '</div>' +

    // Test safety
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🧪 Test safety</div>' +
      '</div>' +
      '<div class="_ats_grid_2">' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsSnap">📸 Snapshot doc</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRestore">↩ Restore</button>' +
      '</div>' +
      '<div class="_ats_section_hint" style="margin-top:6px; margin-bottom:0;">' +
        'Snapshot the doc body before risky edits. Restore reverts back.' +
      '</div>' +
    '</div>' +

    // Logic insertion at cursor (Word)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">➕ Insert logic at cursor</div>' +
      '</div>' +
      '<div class="_ats_section_hint">Drop placeholders and conditional blocks where the cursor is in Word.</div>' +
      '<div class="_ats_logic_row">' +
        '<input id="atsPlaceholderInput" type="text" placeholder="placeholderName" autocomplete="off">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsInsertPh">+ Placeholder</button>' +
      '</div>' +
      '<div class="_ats_logic_row">' +
        '<input id="atsConditionInput" type="text" placeholder="condition (e.g. hasIndemnity)" autocomplete="off">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsWrapCond">↻ Wrap selection if</button>' +
      '</div>' +
      '<div class="_ats_grid_2" style="margin-top:6px;">' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsInsertElse">+ {{else}}</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsInsertEnd">+ {{/if}}</button>' +
      '</div>' +
    '</div>' +

    // Detected tags (from live Word doc)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🔍 Detected in doc <span class="_ats_detected_count" id="atsDetectedCount">0</span></div>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRefreshTags">🔄</button>' +
      '</div>' +
      '<div class="_ats_detected" id="atsDetectedBody"></div>' +
    '</div>' +

    // Logic block tracer — {{#if}} / {{else}} / {{/if}} structure with errors.
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🌳 Logic blocks <span class="_ats_detected_count" id="atsLogicCount">0</span></div>' +
      '</div>' +
      '<div class="_ats_section_hint">Traced from <code>{{#if X}}</code> / <code>{{else}}</code> / <code>{{/if}}</code> (and <code>{{#each}}</code>) in the doc. Click a condition to jump to it. Red blocks have errors (unmatched/duplicated).</div>' +
      '<div id="atsLogicTree" class="_ats_logic_tree"></div>' +
    '</div>' +

    // Template prompts — every {{DEF:...}} gets a typed input. Options
    // come from the DEF syntax (e.g. {{DEF:term=12|6,12,24|months}});
    // text-mode kicks in when options start with `*`. Toggle live
    // preview to push every change to Word automatically.
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🎯 Template prompts</div>' +
        '<label class="_ats_livepreview_toggle" title="Auto-apply changes to the Word doc">' +
          '<input type="checkbox" id="atsLivePreview"' + (_atsState().livePreview ? " checked" : "") + '>' +
          '<span>Live preview</span>' +
        '</label>' +
      '</div>' +
      '<div class="_ats_section_hint">Each <code>{{DEF:key=default|opts|warning}}</code> in the doc becomes a row. Pick a value — the Word doc rebuilds with that choice (IFs evaluated, fill markers substituted). Click the chip to jump.</div>' +
      '<div id="atsPromptList" class="_ats_promptlist"></div>' +
      '<div class="_ats_promptactions">' +
        '<button class="_ats_btn _ats_btn_primary _ats_promptactions_main" id="atsApplyPrompts">⚡ Apply now</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsReturnOriginal" title="Restore the un-substituted template in Word">📜 Return to original</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsCaptureSource" title="Snapshot the current doc as the source the preview rebuilds from">📸 Capture source</button>' +
      '</div>' +
    '</div>' +

    // Metadata (collapsible-feeling at the bottom — small, edit-when-needed)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📌 Metadata</div>' +
      '</div>' +
      '<div id="atsMetadataBody"></div>' +
    '</div>';

  // Wire actions
  document.getElementById("atsLoadInto").onclick = _atsLoadIntoDoc;
  document.getElementById("atsSaveFrom").onclick = _atsSaveFromDoc;
  document.getElementById("atsSnap").onclick = function () {
    _atsSnapshot().then(function (ok) {
      if (typeof showToast === "function") showToast(ok ? "📸 Snapshot taken" : "Snapshot failed", ok ? "ok" : "err");
    });
  };
  document.getElementById("atsRestore").onclick = _atsRestore;
  document.getElementById("atsRefreshTags").onclick = function () {
    if (typeof showToast === "function") showToast("⏳ Scanning doc…", "info");
    _atsDetectTagsLive().then(function (tags) {
      if (typeof showToast === "function") showToast("Found " + tags.length + " tag" + (tags.length === 1 ? "" : "s"), "ok");
    });
  };
  document.getElementById("atsInsertPh").onclick = function () {
    var name = (document.getElementById("atsPlaceholderInput").value || "").trim();
    if (!name) {
      if (typeof showToast === "function") showToast("Enter a placeholder name first.", "warn");
      return;
    }
    _atsInsertAtCursor("{" + name + "}").then(function () {
      if (typeof showToast === "function") showToast("✓ Inserted {" + name + "}", "ok");
      _atsDetectTagsLive();
    });
  };
  document.getElementById("atsWrapCond").onclick = function () {
    var cond = (document.getElementById("atsConditionInput").value || "").trim();
    if (!cond) {
      if (typeof showToast === "function") showToast("Enter a condition first.", "warn");
      return;
    }
    _atsWrapSelection("{{#if " + cond + "}}", "{{/if}}").then(function () {
      if (typeof showToast === "function") showToast("✓ Wrapped selection", "ok");
    });
  };
  document.getElementById("atsInsertElse").onclick = function () {
    _atsInsertAtCursor("{{else}}").then(function () {
      if (typeof showToast === "function") showToast("✓ Inserted {{else}}", "ok");
    });
  };
  document.getElementById("atsInsertEnd").onclick = function () {
    _atsInsertAtCursor("{{/if}}").then(function () {
      if (typeof showToast === "function") showToast("✓ Inserted {{/if}}", "ok");
    });
  };
  document.getElementById("atsApplyPrompts").onclick = function () {
    _atsRunPreview().then(function () {
      if (typeof showToast === "function") showToast("✓ Preview applied", "ok");
    });
  };
  document.getElementById("atsReturnOriginal").onclick = _atsReturnToOriginal;
  document.getElementById("atsCaptureSource").onclick = function () {
    _atsReadDoc().then(function (state) {
      var st = _atsState();
      st.sourceOoxml = state.ooxml || "";
      st.sourceText = state.text || "";
      if (typeof showToast === "function") showToast("📸 Source captured — preview will rebuild from this version.", "ok");
    }).catch(function (err) {
      if (typeof showToast === "function") showToast("Capture failed: " + (err && err.message || "unknown"), "err");
    });
  };
  var liveToggle = document.getElementById("atsLivePreview");
  if (liveToggle) {
    liveToggle.onchange = function () {
      _atsState().livePreview = !!liveToggle.checked;
      if (liveToggle.checked) _atsRunPreview();
    };
  }

  _atsRenderCurrent();
  _atsRenderDetected();
  _atsRenderPrompts();
  _atsRenderLogicTree();
  _atsRenderMetadata();
}

// ── Action handlers ────────────────────────────────────────────────

functions._atsActionNew:
function _atsActionNew() {
  if (!window.eli.ui || !window.eli.ui.prompt) return;
  window.eli.ui.prompt({
    title: "New template",
    message: "Template name:",
    placeholder: "e.g. Service Agreement v2",
    confirmLabel: "Create", cancelLabel: "Cancel",
  }).then(function (name) {
    if (!name || !name.trim()) return;
    var tpl = {
      id: "tpl_" + Date.now(),
      name: name.trim(),
      agreementType: "",
      status: "draft",
      content: "",
      locked: false,
      lastUpdated: Date.now(),
    };
    _atsSaveRow(tpl).then(function () { return _atsLoadAll(); }).then(function (all) {
      _atsState().templates = all;
      _atsState().currentId = tpl.id;
      _atsState().pickerOpen = false;
      _atsRenderAll();
      if (typeof showToast === "function") showToast("Created " + tpl.name, "ok");
    });
  });
}

functions._atsActionDuplicate:
function _atsActionDuplicate() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  var copy = Object.assign({}, tpl, {
    id: tpl.id + "_copy_" + Date.now(),
    name: (tpl.name || tpl.id) + " (copy)",
    status: "draft",
    locked: false,
    lastUpdated: Date.now(),
  });
  _atsSaveRow(copy).then(function () { return _atsLoadAll(); }).then(function (all) {
    _atsState().templates = all;
    _atsState().currentId = copy.id;
    _atsState().pickerOpen = false;
    _atsRenderAll();
    if (typeof showToast === "function") showToast("Duplicated → " + copy.name, "ok");
  });
}

functions._atsActionLock:
function _atsActionLock() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  tpl.locked = !tpl.locked;
  _atsSaveRow(tpl).then(function () { return _atsLoadAll(); }).then(function (all) {
    _atsState().templates = all;
    _atsRenderAll();
    if (typeof showToast === "function") showToast(tpl.locked ? "🔒 Locked" : "🔓 Unlocked", "info");
  });
}

functions._atsActionExport:
function _atsActionExport() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  var blob = new Blob([JSON.stringify(tpl, null, 2)], { type: "application/json" });
  var url = URL.createObjectURL(blob);
  var a = document.createElement("a");
  a.href = url; a.download = (tpl.id || "template") + ".json";
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  if (typeof showToast === "function") showToast("Exported", "ok");
}

functions._atsActionDelete:
function _atsActionDelete() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  if (!window.eli.ui || !window.eli.ui.confirm) return;
  window.eli.ui.confirm({
    variant: "danger", icon: "🗑", title: "Delete template?",
    message: "Permanently remove <b>" + _atsEsc(tpl.name || tpl.id) + "</b> from local IDB.",
    confirmLabel: "Delete", cancelLabel: "Cancel",
  }).then(function (ok) {
    if (!ok) return;
    _atsDeleteById(tpl.id).then(function () {
      _atsState().currentId = null;
      return _atsLoadAll();
    }).then(function (all) {
      _atsState().templates = all;
      _atsRenderAll();
      if (typeof showToast === "function") showToast("Deleted", "info");
    });
  });
}

functions._atsActionImport:
function _atsActionImport() {
  var inp = document.createElement("input");
  inp.type = "file"; inp.accept = ".json,application/json";
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0];
    if (!f) return;
    var reader = new FileReader();
    reader.onload = function (ev) {
      try {
        var parsed = JSON.parse(ev.target.result);
        if (!parsed || !parsed.id) throw new Error("missing id");
        return _atsSaveRow(parsed).then(function () { return _atsLoadAll(); }).then(function (all) {
          _atsState().templates = all;
          _atsState().currentId = parsed.id;
          _atsState().pickerOpen = false;
          _atsRenderAll();
          if (typeof showToast === "function") showToast("✓ Imported " + parsed.id, "ok");
        });
      } catch (e2) {
        if (typeof showToast === "function") showToast("Import failed: " + (e2 && e2.message || "unknown"), "err");
      }
    };
    reader.readAsText(f);
  };
  inp.click();
}

// ── Entry ──────────────────────────────────────────────────────────

functions.showAdminTemplateStudio:
function showAdminTemplateStudio() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ats_root">' +
      '<div class="_ats_header">' +
        '<div class="_ats_header_left">' +
          '<div class="_ats_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ats_header_title">📋 Template Studio</div>' +
          '<div class="_ats_header_sub">Word is the editor. This panel helps add logic + test things.</div>' +
        '</div>' +
        '<div id="atsSaveState" class="_ats_savestate"></div>' +
      '</div>' +

      // Current template bar
      '<div class="_ats_current" id="atsCurrent"></div>' +

      // Collapsible picker
      '<div class="_ats_picker" id="atsPicker">' +
        '<div class="_ats_picker_head" id="atsPickerHead">' +
          '<span class="_ats_picker_title">📂 All templates</span>' +
          '<span style="font-size:9px; color:#94a3b8;" id="atsPickerCount">—</span>' +
          '<span class="_ats_picker_caret">▶</span>' +
        '</div>' +
        '<div class="_ats_picker_body" id="atsPickerBody"></div>' +
      '</div>' +

      // Main body (workflow sections)
      '<div id="atsBody"></div>' +
    '</div>';

  // Picker head toggles open/closed
  document.getElementById("atsPickerHead").onclick = function () {
    var st = _atsState();
    st.pickerOpen = !st.pickerOpen;
    _atsRenderPicker();
  };

  _atsLoadAll().then(function (all) {
    var st = _atsState();
    st.templates = all;
    // Auto-select the most recently-updated template if nothing's selected.
    if (!st.currentId && all.length) {
      var sorted = all.slice().sort(function (a, b) { return (b.lastUpdated || 0) - (a.lastUpdated || 0); });
      st.currentId = sorted[0].id;
    }
    document.getElementById("atsPickerCount").textContent = all.length + " template" + (all.length === 1 ? "" : "s");
    _atsRenderAll();
    _atsRenderPicker();
    // Initial tag scan (best-effort — fails silently if no doc is ready).
    _atsDetectTagsLive();
  });
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateStudio"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminTemplateStudio !== "function") {
      eli.log.event("tool", "admin_template_studio_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Studio failed to load", "err");
      return;
    }
    try { window.showAdminTemplateStudio(); }
    catch (e) {
      eli.log.event("tool", "admin_template_studio_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  eli.register({
    tile: { app_admin_template_studio: _show },
    admin_template_studio: { open: _show },
  });

  eli.log.event("tool", "admin_template_studio_initialized", {});
}

jsonTools.css:
/* admin_template_studio v2 — compact companion panel. Word doc is the
   editor; this tool helps add logic + test things. Single column, fits
   the Word taskpane. Class prefix `_ats_`. */

._ats_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  display: flex; flex-direction: column;
  min-height: 100vh;
}

._ats_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 14px 18px;
  border-bottom: 3px solid #c9a227;
  display: flex; justify-content: space-between; align-items: center;
  flex: 0 0 auto;
}
._ats_header_left { min-width: 0; }
._ats_header_eyebrow {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 1.3px;
  text-transform: uppercase; color: #c9a227;
}
._ats_header_title { font: 800 17px/1.1 "Book Antiqua", Georgia, serif; margin: 2px 0 0 0; }
._ats_header_sub { font-size: 10px; color: rgba(255,255,255,0.65); margin-top: 2px; line-height: 1.4; }
._ats_savestate {
  font-size: 9px; font-weight: 700;
  padding: 3px 8px; border-radius: 100px;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.85);
  letter-spacing: 0.5px; text-transform: uppercase;
}
._ats_saving { background: rgba(201,162,39,0.25); color: #ffd76b; }
._ats_saved  { background: rgba(34,197,94,0.15); color: #6ee7b7; }
._ats_dirty  { background: rgba(245,158,11,0.18); color: #fcd34d; }

/* ─── Current-template bar (always visible) ──────────────────────── */
._ats_current {
  display: grid; grid-template-columns: 1fr auto;
  gap: 10px; align-items: center;
  background: #fff;
  padding: 10px 14px;
  border-bottom: 1px solid #e2e8f0;
}
._ats_current_left { min-width: 0; }
._ats_current_label {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 0.6px;
  text-transform: uppercase; color: #64748b;
}
._ats_current_name {
  font: 800 14px/1.2 Inter, sans-serif; color: #0f172a;
  margin-top: 3px; overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap;
}
._ats_current_meta {
  font-size: 10px; color: #64748b; margin-top: 2px;
  display: flex; gap: 6px; align-items: center;
}
._ats_pill {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 0.5px;
  padding: 2px 6px; text-transform: uppercase;
}
._ats_pill_active   { background: #dcfce7; color: #166534; }
._ats_pill_draft    { background: #fef3c7; color: #92400e; }
._ats_pill_archived { background: #f1f5f9; color: #64748b; }
._ats_current_right { display: flex; gap: 4px; }

._ats_btn {
  padding: 6px 10px; font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px; text-transform: uppercase;
  border: none; cursor: pointer;
  transition: all 0.15s;
  display: inline-flex; align-items: center; gap: 4px;
}
._ats_btn:disabled { opacity: 0.5; cursor: progress; }
._ats_btn_primary { background: #1565c0; color: #fff; }
._ats_btn_primary:hover:not(:disabled) { background: #0d47a1; }
._ats_btn_gold { background: #c9a227; color: #0d1b2a; }
._ats_btn_gold:hover:not(:disabled) { filter: brightness(0.95); }
._ats_btn_ghost { background: #fff; color: #475569; border: 1px solid #cbd5e1; }
._ats_btn_ghost:hover:not(:disabled) { color: #1565c0; border-color: #1565c0; }
._ats_btn_danger { background: #fff; color: #b91c1c; border: 1px solid #fca5a5; }
._ats_btn_danger:hover:not(:disabled) { background: #fef2f2; }
._ats_btn_success { background: #16a34a; color: #fff; }
._ats_btn_success:hover:not(:disabled) { background: #15803d; }

/* ─── Picker (collapsible) ────────────────────────────────────────── */
._ats_picker {
  background: #fff; border-bottom: 1px solid #e2e8f0;
}
._ats_picker_head {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 8px; align-items: center;
  padding: 8px 14px; cursor: pointer;
  border-bottom: 1px solid transparent;
  transition: background 0.15s;
}
._ats_picker_head:hover { background: #f8fafc; }
._ats_picker_open ._ats_picker_head { border-bottom-color: #f1f5f9; }
._ats_picker_caret {
  font-size: 10px; color: #94a3b8;
  transition: transform 0.2s;
}
._ats_picker_open ._ats_picker_caret { transform: rotate(90deg); }
._ats_picker_title {
  font: 800 9px/1 Inter, sans-serif; letter-spacing: 0.6px;
  text-transform: uppercase; color: #475569;
}
._ats_picker_body { display: none; padding: 10px 14px; }
._ats_picker_open ._ats_picker_body { display: block; }

._ats_picker_search {
  position: relative; margin-bottom: 8px;
}
._ats_picker_search input {
  width: 100%; padding: 6px 10px 6px 28px;
  font-size: 11px; border: 1px solid #cbd5e1;
  outline: none; box-sizing: border-box;
}
._ats_picker_search input:focus { border-color: #1565c0; }
._ats_picker_search::before {
  content: "🔍"; position: absolute; left: 8px;
  top: 50%; transform: translateY(-50%);
  font-size: 11px; pointer-events: none;
}

._ats_picker_list { max-height: 220px; overflow-y: auto; }
._ats_picker_card {
  padding: 7px 10px; margin-bottom: 3px;
  border: 1px solid #e2e8f0; background: #fff;
  cursor: pointer; transition: all 0.15s;
}
._ats_picker_card:hover { border-color: #cbd5e1; background: #f8fafc; }
._ats_picker_card._ats_active {
  border-color: #1565c0; background: linear-gradient(180deg, #fff, #e3f2fd 130%);
  box-shadow: inset 3px 0 0 #1565c0;
}
._ats_picker_card_name { font: 800 11px/1.2 Inter, sans-serif; color: #0f172a; }
._ats_picker_card_meta { font-size: 9px; color: #64748b; margin-top: 2px; }

._ats_picker_footer {
  display: flex; gap: 6px; margin-top: 8px;
}
._ats_picker_footer button { flex: 1; padding: 7px; font-size: 9px; }

/* ─── Section blocks ─────────────────────────────────────────────── */
._ats_section {
  background: #fff;
  border-bottom: 1px solid #e2e8f0;
  padding: 12px 14px;
}
._ats_section_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 8px;
}
._ats_section_title {
  font: 800 9px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.6px; color: #475569;
}
._ats_section_hint {
  font-size: 10px; color: #64748b; line-height: 1.4;
  margin-bottom: 8px;
}

._ats_grid_2 {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 6px;
}
._ats_actionbar {
  display: flex; flex-direction: column; gap: 6px;
}
._ats_actionbar ._ats_btn { width: 100%; justify-content: center; padding: 8px; }

/* ─── Insert logic — placeholder + conditional pickers ───────────── */
._ats_logic_row {
  display: grid; grid-template-columns: 1fr auto;
  gap: 6px; margin-bottom: 6px;
}
._ats_logic_row input,
._ats_logic_row select {
  padding: 6px 8px; font-size: 11px;
  border: 1px solid #cbd5e1; outline: none;
  box-sizing: border-box; background: #fff;
}
._ats_logic_row input:focus,
._ats_logic_row select:focus { border-color: #1565c0; }
._ats_logic_row input { font-family: ui-monospace, Consolas, monospace; }

._ats_quick_tags {
  display: flex; flex-wrap: wrap; gap: 4px;
  margin-top: 6px;
}
._ats_quick_tag {
  padding: 3px 7px; font: 700 9px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9; cursor: pointer;
  transition: filter 0.15s;
}
._ats_quick_tag:hover { filter: brightness(0.95); }

/* ─── Detected tags ─────────────────────────────────────────────── */
._ats_detected {
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  min-height: 40px;
}
._ats_detected_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 6px;
}
._ats_detected_count {
  background: #1565c0; color: #fff; padding: 2px 7px;
  font: 800 9px/1 Inter, sans-serif; border-radius: 100px;
}
._ats_detected_empty {
  font-size: 10px; color: #94a3b8; font-style: italic;
}

/* ─── Mock values ───────────────────────────────────────────────── */
._ats_mocklist {
  display: flex; flex-direction: column;
  gap: 4px; max-height: 280px; overflow-y: auto;
}
._ats_mockrow {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
  gap: 4px; align-items: center;
}
._ats_mockrow_label {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  color: #6d28d9; padding: 5px 7px;
  background: #ede9fe; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap;
}
._ats_mockrow input {
  padding: 5px 7px; font-size: 11px;
  border: 1px solid #cbd5e1; outline: none;
  box-sizing: border-box;
}
._ats_mockrow input:focus { border-color: #1565c0; }

._ats_metaedit {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
}
._ats_field_label {
  font: 700 8px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px; color: #64748b; margin-bottom: 3px;
}
._ats_input, ._ats_select {
  width: 100%; padding: 6px 8px; font-size: 11px;
  border: 1px solid #cbd5e1; outline: none;
  background: #fff; box-sizing: border-box;
  transition: border-color 0.15s;
}
._ats_input:focus, ._ats_select:focus { border-color: #1565c0; }

._ats_empty_state {
  padding: 40px 20px; text-align: center; color: #94a3b8;
  background: #fff;
}
._ats_empty_icon { font-size: 48px; opacity: 0.4; margin-bottom: 10px; }
._ats_empty_title { font-size: 13px; font-weight: 700; color: #475569; margin-bottom: 4px; }
._ats_empty_sub { font-size: 11px; }

._ats_toast_msg {
  font-size: 10px; color: #475569;
  padding: 4px 0; font-style: italic;
}

/* ─── Logic block tree ──────────────────────────────────────────── */
._ats_logic_tree {
  display: flex; flex-direction: column;
  gap: 4px;
  border: 1px solid #e2e8f0;
  background: #fafbfc;
  padding: 8px;
  min-height: 40px;
}
._ats_logic_block {
  border-left: 3px solid #1565c0;
  background: #fff;
  padding: 6px 8px;
  font-size: 11px;
}
._ats_logic_block._ats_logic_warn { border-left-color: #f59e0b; }
._ats_logic_block._ats_logic_err  { border-left-color: #dc2626; background: #fef2f2; }

._ats_logic_block_head {
  display: flex; align-items: center; gap: 6px;
  flex-wrap: wrap;
}
._ats_logic_block_kind {
  font: 800 9px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
}
._ats_logic_block_cond {
  font: 700 11px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9;
  border: none; padding: 3px 7px;
  cursor: pointer;
  transition: filter 0.15s;
}
._ats_logic_block_cond:hover { filter: brightness(0.95); }
._ats_logic_block_lines {
  font: 700 9px/1 ui-monospace, Consolas, monospace;
  color: #94a3b8;
  margin-left: auto;
}
._ats_logic_block_err {
  font-size: 10px; color: #b91c1c;
  margin-top: 4px;
  font-weight: 600;
}
._ats_logic_children {
  margin-top: 4px;
  display: flex; flex-direction: column;
  gap: 4px;
}

/* ─── Template prompts (typed, schema-driven) ──────────────────── */
._ats_promptlist {
  display: flex; flex-direction: column;
  gap: 8px;
  max-height: 420px; overflow-y: auto;
  padding-right: 2px;
}
._ats_promptrow {
  border: 1px solid #e2e8f0;
  background: #fff;
  padding: 8px;
}
._ats_promptrow_head {
  display: flex; align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}
._ats_promptrow_chip {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9;
  border: none; padding: 4px 8px;
  cursor: pointer;
  max-width: 50%;
  overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap;
  transition: filter 0.15s;
}
._ats_promptrow_chip:hover { filter: brightness(0.95); }
._ats_promptrow_label {
  font: 700 10px/1.2 Inter, sans-serif;
  color: #475569;
  flex: 1; min-width: 0;
  overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap;
}
._ats_promptrow_type {
  font: 800 8px/1 Inter, sans-serif;
  letter-spacing: 0.5px; text-transform: uppercase;
  background: #f1f5f9; color: #475569;
  padding: 3px 6px;
}
._ats_promptrow_cog {
  padding: 4px 7px !important;
  font-size: 11px !important;
  line-height: 1 !important;
}
._ats_promptrow_warning {
  margin-top: 6px;
  padding: 5px 8px;
  font: 600 10px/1.4 Inter, sans-serif;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  color: #92400e;
}
._ats_promptlist_empty {
  padding: 16px;
  text-align: center;
  font: 500 10.5px/1.4 Inter, sans-serif;
  color: #94a3b8;
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
}
._ats_logic_empty {
  font: 500 10.5px/1.4 Inter, sans-serif;
  color: #94a3b8;
  padding: 8px 4px;
}

/* Live preview toggle — sits in the section head opposite the title */
._ats_livepreview_toggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: 700 9px/1 Inter, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #1565c0;
  cursor: pointer;
}
._ats_livepreview_toggle input {
  margin: 0;
  cursor: pointer;
  accent-color: #1565c0;
}

/* Logic block segments (IF / ELSEIF / ELSE list inside a block head) */
._ats_logic_block_segs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
._ats_logic_seg_active {
  background: linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%) !important;
  color: #166534 !important;
  box-shadow: inset 0 0 0 1px #16a34a;
  font-weight: 800;
}

._ats_promptactions {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}
._ats_promptactions ._ats_btn { flex: 1 1 0; justify-content: center; }
._ats_promptactions_main { flex: 1.6 1 0 !important; }
._ats_textarea {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  resize: vertical;
  min-height: 50px;
}

._ats_schema_editor {
  margin-top: 8px; padding: 10px;
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 130%);
  border: 1px solid #fcd34d;
}
._ats_schema_editor_head {
  font: 800 9px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #92400e;
  margin-bottom: 8px;
}
._ats_schema_editor_head code {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  background: rgba(255,255,255,0.6); padding: 1px 5px;
  color: #6d28d9;
}
._ats_schema_grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 8px; margin-bottom: 6px;
}
._ats_schema_field { min-width: 0; }
._ats_schema_editor > ._ats_schema_field + ._ats_schema_field { margin-top: 6px; }
._ats_schema_editor > ._ats_schema_grid + ._ats_schema_field { margin-top: 6px; }
